<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Login history · UIU Recruitment Portal Admin</title>
  <?php $adminSection = 'login-history'; ?><?= $this->include('admin/_styles') ?>
  <style>.audit-filters{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:20px}.audit-filters input,.audit-filters select{height:38px;border:1px solid #dfe4ec;border-radius:8px;padding:0 10px;background:#fff;font:inherit}.filter-actions{display:flex;gap:8px;align-items:center}.filter-actions button{height:38px;border:0;border-radius:8px;padding:0 15px;background:#168fd4;color:#fff;font-weight:600}.filter-actions a{color:#168fd4;font-size:13px}.status{display:inline-block;padding:4px 8px;border-radius:999px;font-size:11px;font-weight:700}.success{background:#eaf8ef;color:#187345}.failed{background:#fff0f0;color:#a32121}.muted{color:#798196;font-size:12px}.pager{display:flex;justify-content:space-between;align-items:center;margin-top:16px;color:#69778d;font-size:13px}.pager a{color:#168fd4;font-weight:700;margin-left:12px}@media(max-width:900px){.audit-filters{grid-template-columns:repeat(2,1fr)}}@media(max-width:550px){.audit-filters{grid-template-columns:1fr}}\n+  </style>
